from __future__ import annotations

import base64
import hashlib
import io
import zipfile
from pathlib import Path

ARCHIVE_B64 = """"""
EXPECTED_SHA256 = "aebacddf38f80797f358a740efdffa87ad5d27f30db34712fa3264457f509e69"


def main() -> None:
    repo_root = Path(__file__).resolve().parents[1]
    archive = base64.b64decode(ARCHIVE_B64)
    digest = hashlib.sha256(archive).hexdigest()
    if digest != EXPECTED_SHA256:
        raise RuntimeError(f"Asset archive checksum mismatch: {digest}")

    with zipfile.ZipFile(io.BytesIO(archive)) as package:
        package.extractall(repo_root)

    print("Generated KOTC Learning Commons V4 asset pack.")


if __name__ == "__main__":
    main()
